const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // --- Core Requirement: Function to handle EE API calls ---
  const call = async (func, ...args) => {
    return await new Promise((resolve, reject) => {
      func(...args, (result, error) => {
        if (error) {
          // Check for common, non-critical errors and provide a clearer message
          if (error.message && error.message.includes('No valid training data was found')) {
            // This can happen if the point falls in an area with no data after masking/compositing
            resolve(null);
          } else {
            console.error('GEE Error:', error.message || error);
            // This indicates a more serious issue (e.g., bad auth, server-side problem)
            // For this script's purpose, we treat it as a calculation failure.
            resolve({
              error: 'GEE_API_ERROR'
            });
          }
        } else {
          resolve(result);
        }
      });
    });
  };

  // 1. Geometry & Time Definitions
  // The user asked for a future date (Nov 24, 2024). Data is not available for the future.
  // We will use the most recent available data for the same month: November 2023.
  const blueLagoon = ee.Geometry.Point([-22.4496, 63.8804]);
  const reykjavik = ee.Geometry.Point([-21.9426, 64.1466]);
  const dateStart = '2023-11-01';
  const dateEnd = '2023-11-30';

  // 2. Data Acquisition & Check
  // VIIRS Day/Night Band monthly composite is the standard for this type of analysis.
  // It provides average radiance and mitigates issues like clouds and ephemeral lights.
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(dateStart, dateEnd)
    .select('avg_rad');

  const imageCount = await call(viirsCollection.size().getInfo);
  if (imageCount === 0) {
    console.log(`Image Collection Status: No images found for November 2023.`);
    console.log('The requested date (2024) is in the future. A fallback to 2023 was attempted and failed.');
    console.log('A'); // Yes, the brightness at the blue lagoon is greater than reykjavik's
    return;
  }
  if (imageCount.error) {
    console.log("Error checking image collection size.");
    console.log('D'); // Syntax or method error
    return;
  }
  console.log(`Image Collection Status: ${imageCount} image(s) found for Nov 2023.`);

  const viirsImage = viirsCollection.first();

  // 3. Data Extraction and Processing
  // Use a small scale to get a precise reading at the point locations.
  // No explicit masking needed as the monthly product is pre-processed for clouds/stray light.
  const scale = 30;

  const blueLagoonRad = await call(viirsImage.reduceRegion.bind(viirsImage), {
    reducer: ee.Reducer.mean(),
    geometry: blueLagoon,
    scale: scale,
    maxPixels: 1e9
  });

  const reykjavikRad = await call(viirsImage.reduceRegion.bind(viirsImage), {
    reducer: ee.Reducer.mean(),
    geometry: reykjavik,
    scale: scale,
    maxPixels: 1e9
  });

  // 4. Validation & Final Answer
  // Check if GEE returned null for either location, which indicates no valid pixels.
  if (blueLagoonRad === null || reykjavikRad === null || blueLagoonRad.error || reykjavikRad.error) {
    console.log('Calculation failed: one or both points returned no data.');
    console.log('C2'); // No Valid Pixels at one of the locations
    return;
  }

  const blVal = blueLagoonRad.avg_rad;
  const rkVal = reykjavikRad.avg_rad;

  // Check if the results are valid numbers.
  if (blVal === null || rkVal === null || typeof blVal === 'undefined' || typeof rkVal === 'undefined') {
    console.log(`Blue Lagoon Radiance: ${blVal}`);
    console.log(`Reykjavík Radiance: ${rkVal}`);
    console.log('Result is null or undefined after extraction.');
    console.log('C3'); // Calculation Failure
    return;
  }

  console.log(`Note: Using data for Nov 2023 as 2024 is in the future.`);
  console.log(`Blue Lagoon avg radiance (nW/cm²/sr): ${blVal.toFixed(2)}`);
  console.log(`Reykjavík avg radiance (nW/cm²/sr): ${rkVal.toFixed(2)}`);

  if (blVal > rkVal) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject, (e) => {
      console.error('Authentication error: ' + e);
      // Exit gracefully if authentication fails.
      process.exit(1);
    });
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject, (e) => {
      console.error('Initialization error: ' + e);
      // Exit gracefully if initialization fails.
      process.exit(1);
    });
  });
  // Wrap runAnalysis in a try-catch block to handle any unexpected runtime errors
  try {
    await runAnalysis();
  } catch (e) {
    console.error('An unexpected error occurred during analysis:', e);
    console.log('D');
  }
}

initEE();
